policy:
{
  // Tailscale SSH. "accept" connects straight through; "check" forces a fresh
  // browser re-auth. Add two ssh rules: engineers get accept-SSH to tag:web as
  // autogroup:nonroot, and sales get check-SSH to the same.
  "groups": {
    "group:eng": ["alice@example.com", "bob@example.com"],
    "group:sales": ["carol@example.com"],
  },
  "tagOwners": {
    "tag:web": ["group:eng"],
    "tag:db": ["group:eng"],
  },
  "grants": [
    { "src": ["group:eng", "group:sales"], "dst": ["tag:web"], "ip": ["tcp:22"] },
  ],
  "ssh": [
    // TODO
  ],
  "sshTests": [
    { "src": "alice@example.com", "dst": ["tag:web"], "accept": ["ubuntu"], "deny": ["root"] },
    { "src": "carol@example.com", "dst": ["tag:web"], "check": ["ubuntu"] },
  ],
}
